-    NON_REFUNDABLE
+    NON_REFUNDABLE,
+    /** A discount agreed with the guest's company. */
+    CORPORATE,
+    /** Friday to Sunday for a fixed price per room type. */
+    WEEKEND_PACKAGE,
+    /** 7 nights or more, 10% off. */
+    LONG_STAY
 }
