 10	
 11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 12	public final class ReservationService {
 13	
 14	    static final String HOTEL_NAME = "Pousada Maré Alta";
 15	
 16	    private final Rooms rooms;
 17	    private final ReservationStore store;
 18	    private final PriceCalculator priceCalculator;
 19	    private final EmailSender emailSender;
 20	
 21	    public ReservationService(
 22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 23	        this.rooms = rooms;
 24	        this.store = store;
 25	        this.priceCalculator = priceCalculator;
 26	        this.emailSender = emailSender;
 27	    }
 28	
 29	    public synchronized Reservation create(NewReservation request) {
 30	        if (!request.checkOut().isAfter(request.checkIn())) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 32	        }
 33	        if (request.guests() < 1) {
 34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 35	        }
 36	        Room room = rooms.find(request.roomNumber())
 37	                .orElseThrow(() -> new HotelException(
 38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 39	        if (request.guests() > room.capacity()) {
 40	            throw new HotelException(
 41	                    ErrorCode.CAPACITY_EXCEEDED,
 42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 43	        }
 44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 45	            throw new HotelException(
 46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 47	        }
 48	        if (request.ratePlan() == RatePlan.CORPORATE
 49	                && (request.companyCode() == null
 50	                    || !PriceCalculator.COMPANY_DISCOUNTS.containsKey(request.companyCode()))) {
 51	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 52	                    "the CORPORATE plan needs the code of a company with an agreement");
 53	        }
 54	        if (request.ratePlan() == RatePlan.WEEKEND_PACKAGE
 55	                && (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY
 56	                    || !request.checkOut().equals(request.checkIn().plusDays(2)))) {
 57	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 58	                    "the weekend package goes from a Friday to the Sunday right after");
 59	        }
 60	        if (request.ratePlan() == RatePlan.LONG_STAY
 61	                && ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()) < 7) {
 62	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the long stay needs at least 7 nights");
 63	        }
 64	        Price price = priceCalculator.calculate(
 65	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 66	        return store.add(request, price);
 67	    }
 68	
 69	    public Reservation find(long reservationId) {
 70	        return store.find(reservationId)
 71	                .orElseThrow(() -> new HotelException(
 72	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 73	    }
 74	
 75	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 76	    public synchronized Reservation confirm(long reservationId) {
 77	        Reservation reservation = find(reservationId);
 78	        if (reservation.status() != ReservationStatus.PENDING) {
 79	            throw notAllowed(reservation, "confirm");
 80	        }
 81	        reservation.confirmPayment();
 82	        store.update(reservation);
 83	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 84	        emailSender.send(
 85	                reservation.guest().email(),
 86	                "Reserva confirmada - " + HOTEL_NAME,
 87	                confirmationEmailBody(reservation, receipt));
 88	        return reservation;
 89	    }
 90	
 91	    /**
 92	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 93	     * reservation was never paid, so nothing comes back).
 94	     */
 95	    public synchronized Reservation cancel(long reservationId) {
 96	        Reservation reservation = find(reservationId);
 97	        if (reservation.status() != ReservationStatus.PENDING
 98	                && reservation.status() != ReservationStatus.CONFIRMED) {
 99	            throw notAllowed(reservation, "cancel");
100	        }
101	        BigDecimal refund = switch (reservation.ratePlan()) {
102	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
103	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
104	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
105	        };
106	        reservation.cancel(refund);
107	        store.update(reservation);
108	        return reservation;
109	    }
110	
111	    public synchronized Reservation checkIn(long reservationId) {
112	        Reservation reservation = find(reservationId);
113	        if (reservation.status() != ReservationStatus.CONFIRMED) {
114	            throw notAllowed(reservation, "check in");
115	        }
116	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
117	        store.update(reservation);
118	        return reservation;
119	    }
120	
121	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
122	    public synchronized ReservationReceipt checkOut(long reservationId) {
123	        Reservation reservation = find(reservationId);
124	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
125	            throw notAllowed(reservation, "check out");
126	        }
127	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
128	        store.update(reservation);
129	        return new ReservationReceipt(reservation, roomOf(reservation));
130	    }
131	
132	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
133	    public ReservationReceipt receiptCopy(long reservationId) {
134	        Reservation reservation = find(reservationId);
135	        if (!reservation.isPaid()) {
136	            throw notAllowed(reservation, "issue a receipt for");
137	        }
138	        return new ReservationReceipt(reservation, roomOf(reservation));
139	    }
140	
141	    private Room roomOf(Reservation reservation) {
142	        return rooms.find(reservation.roomNumber()).orElseThrow();
143	    }
144	
145	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
146	        return "Olá, " + reservation.guest().name() + "!\n\n"
147	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
148	                + receipt.text() + "\n"
149	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
150	                + "Até breve!\n";
151	    }
152	
153	    private static HotelException notAllowed(Reservation reservation, String operation) {
154	        return new HotelException(
155	                ErrorCode.OPERATION_NOT_ALLOWED,
156	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
157	    }
158	}
159	package hotel.reservations;
