161	import hotel.rooms.Room;
162	import java.math.BigDecimal;
163	import java.math.RoundingMode;
164	import java.time.LocalDate;
165	import java.time.Month;
166	import java.util.Map;
167	
168	/**
169	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
170	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
171	 * (half-even) at every step.
172	 */
173	public final class PriceCalculator {
174	
175	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
176	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
177	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
178	    static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
179	            "TECNOSUL", new BigDecimal("0.12"),
180	            "AGROVALE", new BigDecimal("0.18"),
181	            "FARMAVIDA", new BigDecimal("0.25"));
182	
183	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
184	        int nights = 0;
185	        BigDecimal subtotal = cents(BigDecimal.ZERO);
186	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
187	            subtotal = subtotal.add(nightPrice(room, night));
188	            nights++;
189	        }
190	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
191	            BigDecimal packagePrice = switch (room.type()) {
192	                case STANDARD -> new BigDecimal("520.00");
193	                case DELUXE -> new BigDecimal("820.00");
194	                case SUITE -> new BigDecimal("1200.00");
195	            };
196	            return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
197	        }
198	        BigDecimal discount = switch (ratePlan) {
199	            case STANDARD -> cents(BigDecimal.ZERO);
200	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
201	            case CORPORATE -> cents(subtotal.multiply(COMPANY_DISCOUNTS.get(companyCode)));
202	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
203	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
204	        };
205	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
206	    }
207	
208	    BigDecimal nightPrice(Room room, LocalDate night) {
209	        BigDecimal nightlyRate = room.nightlyRate();
210	        if (isHighSeason(night)) {
211	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
212	        }
213	        return cents(nightlyRate);
214	    }
215	
216	    /** High season: from December 15 to the end of February, and the whole of July. */
217	    static boolean isHighSeason(LocalDate date) {
218	        Month month = date.getMonth();
219	        return month == Month.JANUARY
220	                || month == Month.FEBRUARY
221	                || month == Month.JULY
222	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
223	    }
224	
225	    static BigDecimal cents(BigDecimal value) {
226	        return value.setScale(2, RoundingMode.HALF_EVEN);
227	    }
228	}
